const KEY='tacticalQaStateV2';
const defaults=()=>({date:'2026-10-12',capacity:5,used:4,tickets:0,claimedKey:null,version:'buggy',rule:'daily',lastMessage:'补给已就绪'});
function load(){try{return {...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return defaults()}}
function save(s){localStorage.setItem(KEY,JSON.stringify(s));render();window.dispatchEvent(new CustomEvent('qa-state-change',{detail:s}))}
// 被测程序保持“按日”实现。需求改为“永久一次”时，QA 预期会改变，
// 但不会偷偷改动被测逻辑来迎合新需求，因此跨日用例会真实暴露差异。
function eligibilityKey(s){return s.date}
function claim(){let s=load(),key=eligibilityKey(s);if(s.claimedKey===key){s.lastMessage='今日已领取：不可重复发奖';save(s);return {ok:false,code:'ALREADY_CLAIMED'}}if(s.version==='buggy')s.claimedKey=key;if(s.used>=s.capacity){s.lastMessage='背包已满：补给发放失败';save(s);return {ok:false,code:'BAG_FULL'}}s.used++;s.tickets++;s.claimedKey=key;s.lastMessage='领取成功：训练券 × 1';save(s);return {ok:true,code:'SUCCESS'}}
function render(){const s=load();document.querySelector('#bagText').textContent=`${s.used} / ${s.capacity}`;document.querySelector('#bagNavCount').textContent=`${s.used}/${s.capacity}`;document.querySelector('#dateText').textContent=s.date.replaceAll('-','.');document.querySelector('#slots').innerHTML=Array.from({length:s.capacity},(_,i)=>`<i class="slot ${i<s.used?'used':''} ${i>=s.used-s.tickets&&i<s.used?'ticket-used':''}"></i>`).join('');let f=document.querySelector('#feedback');f.textContent=s.lastMessage;f.className='feedback '+(s.lastMessage.includes('成功')?'ok':s.lastMessage.includes('失败')||s.lastMessage.includes('已领取')?'bad':'');document.querySelector('#bagDetail').textContent=`已用 ${s.used}/${s.capacity}，训练券 ${s.tickets} 张`;document.querySelector('#bagItems').innerHTML=Array.from({length:s.used},(_,i)=>`<div class="bag-item">${i>=s.used-s.tickets?'训练券 · 不可叠加':'训练道具 '+(i+1)}</div>`).join('')||'<p>背包为空</p>'}
window.QA_GAME={reset(opts={}){save({...defaults(),version:opts.version||load().version,rule:opts.rule||load().rule});return load()},fill(){let s=load();s.used=s.capacity;s.tickets=0;s.lastMessage='测试准备：背包已填满';save(s);return load()},clear(){let s=load();s.used=0;s.tickets=0;s.lastMessage='测试准备：背包已清空';save(s);return load()},advance(){let s=load(),d=new Date(s.date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);s.date=d.toISOString().slice(0,10);s.lastMessage='测试时钟已推进一天';save(s);return load()},state:load,claim};
document.querySelector('#claimButton').onclick=claim;document.querySelector('#viewBag').onclick=document.querySelector('#bagNav').onclick=()=>document.querySelector('#bagDrawer').classList.add('open');document.querySelector('#closeBag').onclick=()=>document.querySelector('#bagDrawer').classList.remove('open');window.addEventListener('storage',render);render();
